 8633	static uint64_t CjguiCaretBlinkHalfPeriodMicros(void) {
 8634	#ifdef CJGUI_INTERNAL_TESTING
 8635	    const char *injected = getenv("CJGUI_TEST_CARET_BLINK_HALF_PERIOD_MS");
 8636	    if (injected && *injected) {
 8637	        char *end = NULL;
 8638	        double milliseconds = strtod(injected, &end);
 8639	        if (end != injected && *end == '\0' && milliseconds >= 0.0 && milliseconds <= 10000.0)
 8640	            return milliseconds == 0.0 ? 0 : (uint64_t)(milliseconds * 1000.0);
 8641	    }
 8642	#endif
 8643	    id preference = [[NSUserDefaults standardUserDefaults] objectForKey:@"NSTextInsertionPointBlinkPeriod"];
