+                (unsigned long)base.length, (unsigned long)old.length,
+                [[base substringToIndex:MIN(base.length, (NSUInteger)48)] UTF8String],
+                [[old substringToIndex:MIN(old.length, (NSUInteger)48)] UTF8String]);
