+            reusableBytes = bytes > UINT64_MAX - reusableBytes ? UINT64_MAX : reusableBytes + bytes;
+        }
+    }
+    outWorkload->reusableResourceBytes = reusableBytes;
+    return CJGUI_INTERNAL_RENDERER_OK;
+}
