49	        [overlay scheduleCaretBlink];  // unchanged declaration/geometry cannot reset the clock
50	        if (overlay.caretBlinkDeadlineMicros != 1010000) return fail("same target reset deadline");
51	        [overlay advanceCaretBlinkAtMicros:1010000];
52	        if (!node.textCaretHidden || overlay.presents != 1 ||
