56	        [overlay advanceCaretBlinkAtMicros:1020000];
57	        if (node.textCaretHidden || overlay.presents != 2) return fail("hidden to visible");
58	        if (CjguiEffectHashPaintNode(1469598103934665603ULL, node, node.node) != visiblePaintHash)
